            user2_interests = set(match["languages"])
            if user1_interests & user2_interests:
                # Create session
                session_id = f"sess_{len(self.sessions)+1}"
                session = LanguageExchangeSession(
                    session_id=session_id,
                    user1_id=user_id,
                    user2_id=match["user_id"],
                    language1=list(user1_interests & user2_interests)[0],
                    language2=list(user2_interests - user1_interests)[0] if user2_interests - user1_interests else list(user1_interests & user2_interests)[0],
                    start_time=None,
                    status="scheduled"
