import hashlib
import re
from datetime import datetime

class User:
    def __init__(self, username, email, password, cultural_background=None, interests=None):
        self.username = username
        self.email = email
        self._password_hash = self._hash_password(password)
        self.cultural_background = cultural_background or ""
        self.interests = interests or []
        self.profile_picture = None
        self.created_at = datetime.utcnow()

    @staticmethod
    def _hash_password(password):
        """Hash password using SHA-256."""
        return hashlib.sha256(password.encode('utf-8')).hexdigest()

    def verify_password(self, password):
        return self._password_hash == self._hash_password(password)

    def update_profile(self, cultural_background=None, interests=None, profile_picture=None):
        if cultural_background is not None:
            self.cultural_background = cultural_background
        if interests is not None:
            self.interests = list(set(self.interests + interests))
        if profile_picture:
            self.profile_picture = profile_picture

    def __repr__(self):
        return f"<User {self.username}>"


class UserRegistry:
    def __init__(self):
        self._users = {}  # username -> User

    def register(self, username, email, password, cultural_background=None, interests=None):
        if username in self._users:
            raise ValueError("Username already exists")
        if not re.match(r"^[a-zA-Z0-9_.-]+$", username):
            raise ValueError("Invalid username format")
        if not re.match(r"^[^@]+@[^@]+\.[^@]+$", email):
            raise ValueError("Invalid email format")
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters")
        user = User(username, email, password, cultural_background, interests)
        self._users[username] = user
        return user

    def get_user(self, username):
        return self._users.get(username)

    def authenticate(self, username, password):
        user = self._users.get(username)
        if user and user.verify_password(password):
            return user
        return None


