    def __init__(self, id: str, label: str, description: str, audio_url: Optional[str] = None):
        self.id = id
        self.label = label
        self.description = description
        self.audio_url = audio_url


class VirtualTour:
    def __init__(self, tour_id: str, title: str, location: str, model_url: str):
        self.tour_id = tour_id
        self.title = title
        self.location = location
        self.model_url = model_url
        self.hotspots: Dict[str, Hotspot] = {}
        self.audio_guides: Dict[str, str] = {}  # hotspot_id -> audio_url

    def add_hotspot(self, hotspot: Hotspot):
        self.hotspots[hotspot.id] = hotspot
        if hotspot.audio_url:
            self.audio_guides[hotspot.id] = hotspot.audio_url

    def get_hotspot(self, hotspot_id: str) -> Optional[Hotspot]:
        return self.hotspots.get(hotspot_id)

    def to_dict(self) -> dict:
        return {
            "tour_id": self.tour_id,
            "title": self.title,
            "location": self.location,
            "model_url": self.model_url,
            "hotspots": [
                {
                    "id": hs.id,
                    "label": hs.label,
                    "description": hs.description,
                    "audio_url": hs.audio_url
                }
                for hs in self.hotspots.values()
            ]
        }


class VirtualTourManager:
    def __init__(self):
        self._tours: Dict[str, VirtualTour] = {}

    def add_tour(self, tour: VirtualTour):
        self._tours[tour.tour_id] = tour

    def get_tour(self, tour_id: str) -> Optional[VirtualTour]:
        return self._tours.get(tour_id)

    def list_tours(self) -> List[VirtualTour]:
        return list(self._tours.values())

    def search_tours(self, keyword: str) -> List[VirtualTour]:
        keyword = keyword.lower()
        return [
            tour for tour in self._tours.values()
            if keyword in tour.title.lower() or keyword in tour.location.lower()
        ]


