import random
from typing import Dict, List, Optional, Tuple
from datetime import datetime

class LanguageExchangeSession:
    def __init__(self, session_id: str, user1: str, user2: str, languages: List[str]):
        self.session_id = session_id
        self.user1 = user1
        self.user2 = user2
        self.languages = languages
        self.start_time = datetime.utcnow()
        self.end_time = None
        self.messages = []

    def add_message(self, sender: str, text: str, translated_text: Optional[str] = None):
        self.messages.append({
            "sender": sender,
            "text": text,
            "translated": translated_text,
            "timestamp": datetime.utcnow().isoformat()
        })

    def end(self):
        self.end_time = datetime.utcnow()


class TranslationService:
    """Mock translation service for demonstration."""
    def __init__(self):
        self._dictionary = {
            ("hello", "es"): "hola",
            ("hello", "fr"): "bonjour",
            ("goodbye", "es"): "adiós",
            ("goodbye", "fr"): "au revoir",
            ("thank you", "es"): "gracias",
            ("thank you", "fr"): "merci",
        }

    def translate(self, text: str, target_lang: str) -> str:
        key = (text.lower(), target_lang)
        if key in self._dictionary:
            return self._dictionary[key].capitalize() if text[0].isupper() else self._dictionary[key]
        return f"[TRANSLATION: {text} -> {target_lang}]"


class LanguageExchangeManager:
    def __init__(self, user_registry, translation_service=None):
        self.user_registry = user_registry
        self.translation_service = translation_service or TranslationService()
        self._sessions: Dict[str, LanguageExchangeSession] = {}
        self._waiting_users: List[str] = []  # usernames looking for a partner

    def find_partner(self, user: str, preferred_languages: List[str]) -> Optional[str]:
        # Simple matching: find first user in waiting list with matching language
        for candidate in self._waiting_users:
            if candidate != user:
                # In real system, would check candidate's preferred languages
                return candidate
        return None

    def start_session(self, user1: str, user2: str, languages: List[str]) -> Optional[LanguageExchangeSession]:
        if user1 not in self.user_registry._users or user2 not in self.user_registry._users:
            return None
        session_id = f"sess_{len(self._sessions) + 1}"
        session = LanguageExchangeSession(session_id, user1, user2, languages)
        self._sessions[session_id] = session
        return session

    def send_message(self, session_id: str, sender: str, text: str, target_lang: str) -> bool:
        session = self._sessions.get(session_id)
        if not session:
            return False
        translated = self.translation_service.translate(text, target_lang)
        session.add_message(sender, text, translated)
        return True

    def end_session(self, session_id: str):
        session = self._sessions.get(session_id)
        if session:
            session.end()


